import React, { useEffect, useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { Menubar } from "primereact/menubar";
import { Avatar } from "primereact/avatar";
import { Menu } from "primereact/menu";

export const Navigation = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [avatar, setAvatar] = useState("/assets/default-avatar.png");
  const menuRef = useRef(null);
  const navigate = useNavigate();

  useEffect(() => {
    const token = localStorage.getItem("token");
    setIsLoggedIn(!!token);

    const ownerData = localStorage.getItem("owner");
    if (ownerData) {
      try {
        const owner = JSON.parse(ownerData);
        setAvatar(owner.avatar || "/assets/default-avatar.png");
      } catch (error) {
        console.error("Error parsing owner data:", error);
      }
    }
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("ownerId");
    setIsLoggedIn(false);
    setAvatar("/assets/default-avatar.png");
    navigate("/login");
  };

  const handleProfileClick = () => {
    const ownerId = localStorage.getItem("ownerId");
    if (ownerId) {
      navigate(`/profile/${ownerId}`);
    }
  };

  const menuItems = [
    { label: "Home", icon: "pi pi-home", command: () => navigate("/") },
    !isLoggedIn && { label: "Log In", icon: "pi pi-sign-in", command: () => navigate("/login") },
  ].filter(Boolean);

  const userMenuItems = [
    { label: "Profile", icon: "pi pi-user", command: handleProfileClick },
    { label: "Logout", icon: "pi pi-sign-out", command: handleLogout },
  ];

  return (
    <div className="shadow-md">
      <Menubar
        model={menuItems}
        start={
          <img
            src={require("../assets/Logo.png")}
            alt="Petopia Logo"
            className="h-12 w-auto cursor-pointer"
            onClick={() => navigate("/")}
            style={{maxWidth: '250px'}}
          />
        }
        end={
          
          isLoggedIn && (
            <div className="flex items-center gap-4">
              <Avatar
                image={avatar}
                className="cursor-pointer"
                shape="circle"
                onClick={(e) => menuRef.current.toggle(e)}
              />
              <Menu model={userMenuItems} popup ref={menuRef} />
            </div>
          )
        }
        className="p-3 bg-white flex justify-between"
      />
    </div>
  );
};
